#include <iostream>
#include <string>

std::string encode(const std::string& s)
{
    std::string out{};
    std::size_t i{ 0 };

    while (i < s.size())
    {
        std::size_t j{ i };
        while (j < s.size() && s[j] == s[i]) ++j;

        const std::size_t run{ j - i };
        out += s[i];
        if (run > 1) out += std::to_string(run);

        i = j;
    }

    return out;
}

std::string decode(const std::string& s)
{
    std::string out{};
    std::size_t i{ 0 };

    while (i < s.size())
    {
        const char c{ s[i] };
        ++i;

        std::size_t n{ 0 };
        while (i < s.size() && s[i] >= '0' && s[i] <= '9')
        {
            n = n * 10 + static_cast<std::size_t>(s[i] - '0');
            ++i;
        }

        out.append(n == 0 ? 1 : n, c);
    }

    return out;
}

int main()
{
    std::string what;
    std::cin >> what;

    std::string payload;
    std::getline(std::cin, payload);
    if (!payload.empty() && payload.front() == ' ') payload.erase(0, 1);

    std::cout << (what == "encode" ? encode(payload) : decode(payload)) << '\n';
    return 0;
}

