import sys


def encode(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        run = j - i
        out.append(s[i])
        if run > 1:
            out.append(str(run))
        i = j
    return "".join(out)


def decode(s):
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        i += 1
        n = 0
        while i < len(s) and s[i].isdigit():
            n = n * 10 + int(s[i])
            i += 1
        out.append(c * (n if n else 1))
    return "".join(out)


def main():
    line = sys.stdin.readline().rstrip("\n")
    what, _, payload = line.partition(" ")
    print(encode(payload) if what == "encode" else decode(payload))


